struct Creator: Codable, Hashable { var id:String; var name:String; var handle:String; var bio:String; var photo:String? }
struct Media: Hashable { enum Kind { case video,image }; let id:String; let url:URL; let kind:Kind; var creatorID:String? }
struct State: Codable { var creators:[Creator]=[]; var assignments:[String:String]=[:]; var likes:[String:Bool]=[:] }

final class Store {
    static let shared = Store(); let fm=FileManager.default
    let root:URL, mediaDir:URL, stateURL:URL
    private(set) var state=State(); private(set) var media:[Media]=[]; var changed:(()->Void)?
    private init(){ let b=fm.urls(for:.applicationSupportDirectory,in:.userDomainMask)[0]; root=b.appendingPathComponent("CornBox"); mediaDir=root.appendingPathComponent("media"); stateURL=root.appendingPathComponent("native-state-v4.json"); try? fm.createDirectory(at:mediaDir,withIntermediateDirectories:true); load(); scan(false) }
    var creators:[Creator]{state.creators}
    func creator(_ m:Media)->Creator?{ guard let id=m.creatorID else{return nil}; return state.creators.first{$0.id==id} }
    func count(_ id:String)->Int{media.filter{$0.creatorID==id}.count}
    func liked(_ id:String)->Bool{state.likes[id] == true}
    func toggle(_ id:String){state.likes[id] = !liked(id); save()}
    func assign(_ mediaID:String,_ creatorID:String?){ if let creatorID{state.assignments[mediaID]=creatorID}else{state.assignments.removeValue(forKey:mediaID)}; scan(false); save() }
    func saveCreator(_ c:Creator){if let i=state.creators.firstIndex(where:{$0.id==c.id}){state.creators[i]=c}else{state.creators.append(c)};save()}
    func scan(_ notify:Bool=true){let v:Set<String>=["mp4","mov","m4v"], im:Set<String>=["jpg","jpeg","png","heic","heif","webp"]; let u=(try? fm.contentsOfDirectory(at:mediaDir,includingPropertiesForKeys:[.contentModificationDateKey])) ?? []; media=u.sorted{((try?$0.resourceValues(forKeys:[.contentModificationDateKey]).contentModificationDate) ?? .distantPast) > ((try?$1.resourceValues(forKeys:[.contentModificationDateKey]).contentModificationDate) ?? .distantPast)}.compactMap{x in let e=x.pathExtension.lowercased(); let k:Media.Kind; if v.contains(e){k = .video}else if im.contains(e){k = .image}else{return nil}; return Media(id:x.lastPathComponent,url:x,kind:k,creatorID:state.assignments[x.lastPathComponent])}; if notify{changed?()} }
    func importFiles(_ urls:[URL],done:@escaping()->Void){let d=mediaDir; DispatchQueue.global(qos:.userInitiated).async{for s in urls{autoreleasepool{let access=s.startAccessingSecurityScopedResource(); defer{if access{s.stopAccessingSecurityScopedResource()}}; var dest=d.appendingPathComponent(s.lastPathComponent), n=2; while FileManager.default.fileExists(atPath:dest.path){let stem=(s.lastPathComponent as NSString).deletingPathExtension, ext=s.pathExtension; dest=d.appendingPathComponent("\(stem)-\(n).\(ext)");n+=1};try? FileManager.default.copyItem(at:s,to:dest)}};DispatchQueue.main.async{self.scan();done()}}}
    private func load(){if let d=try? Data(contentsOf:stateURL),let s=try? JSONDecoder().decode(State.self,from:d){state=s}else{ migrateOldState() }}
    private func migrateOldState(){ for name in ["native-state-v3.json","native-state-v2.json","native-state.json"]{let u=root.appendingPathComponent(name); guard let d=try? Data(contentsOf:u),let obj=try? JSONSerialization.jsonObject(with:d) as? [String:Any] else{continue}; if let rows=obj["creators"] as? [[String:Any]]{state.creators=rows.compactMap{r in guard let id=r["id"] as? String,let name=r["name"] as? String else{return nil};return Creator(id:id,name:name,handle:r["handle"] as? String ?? "",bio:r["bio"] as? String ?? "",photo:r["photo"] as? String)}};state.assignments=obj["assignments"] as? [String:String] ?? [:];state.likes=obj["liked"] as? [String:Bool] ?? [:];persistOnly();return} }
    private func persistOnly(){if let d=try? JSONEncoder().encode(state){try? d.write(to:stateURL,options:.atomic)}}
    private func save(){persistOnly();changed?()}
}

