    func tabBarController(_ t:UITabBarController,shouldSelect v:UIViewController)->Bool{if v===plus{addMenu();return false};return true}
    func show(_ id:String){feed.open(id);selectedIndex=0}
    func addMenu(){let s=UIAlertController(title:"Add to CornBox",message:"Bring something into your little media universe ✦",preferredStyle:.actionSheet);s.addAction(.init(title:"Photos",style:.default){_ in var c=PHPickerConfiguration(photoLibrary:.shared());c.filter=.any(of:[.images,.videos]);c.selectionLimit=0;let p=PHPickerViewController(configuration:c);p.delegate=self;self.present(p,animated:true)});s.addAction(.init(title:"Files",style:.default){_ in let p=UIDocumentPickerViewController(forOpeningContentTypes:[.image,.movie],asCopy:true);p.allowsMultipleSelection=true;p.delegate=self;self.present(p,animated:true)});s.addAction(.init(title:"Cancel",style:.cancel));present(s,animated:true)}
    func documentPicker(_ c:UIDocumentPickerViewController,didPickDocumentsAt urls:[URL]){store.importFiles(urls){} }
    func picker(_ picker:PHPickerViewController,didFinishPicking results:[PHPickerResult]){picker.dismiss(animated:true);let g=DispatchGroup();let lock=NSLock();var urls:[URL]=[];for r in results{let p=r.itemProvider;let id=p.hasItemConformingToTypeIdentifier(UTType.movie.identifier) ? UTType.movie.identifier:UTType.image.identifier;g.enter();p.loadFileRepresentation(forTypeIdentifier:id){u,_ in defer{g.leave()};guard let u else{return};let tmp=FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString+"-"+u.lastPathComponent);if (try? FileManager.default.copyItem(at:u,to:tmp)) != nil{lock.lock();urls.append(tmp);lock.unlock()}}};g.notify(queue:.main){self.store.importFiles(urls){}}}
}

